flowchart TD
    A[业务访问模式分析] --> B{需要跨表事务和复杂 join?}
    B -- 是 --> C{数据规模超单机上限?}
    C -- 否 --> R1[关系型 MySQL/PostgreSQL]
    C -- 是 --> R2[NewSQL: TiDB/CockroachDB]
    B -- 否 --> D{查询模式是否固定且围绕主键?}
    D -- 固定主键 --> E{数据模型是聚合文档?}
    E -- 是 --> R3[文档型: MongoDB/Couchbase]
    E -- 否 --> F{需要多跳关系遍历?}
    F -- 是 --> R4[图数据库: Neo4j/JanusGraph]
    F -- 否 --> G{写入量极大且可容忍最终一致?}
    G -- 是 --> R5[列族 AP: Cassandra]
    G -- 否 --> R6[列族 CP: HBase]
    D -- 不固定 --> H{是否纯 KV 访问?}
    H -- 是 --> R7[键值: Redis/DynamoDB]
    H -- 否 --> R3

// Cassandra 写入时指定一致性级别
// ONE: 只需 1 个副本确认即返回——延迟最低，但可能读到旧数据
// QUORUM: 需要多数派副本确认——读写都用 QUORUM 可实现强一致
// ALL: 所有副本确认——一致性最强但可用性最差，任一副本宕机即失败

import com.datastax.driver.core.ConsistencyLevel;
import com.datastax.driver.core.Session;
import com.datastax.driver.core.PreparedStatement;

// 写入：指定 QUORUM，保证多数副本持久化
PreparedStatement writeStmt = session.prepare(
    "INSERT INTO user_activity (user_id, event_time, event_type) VALUES (?, ?, ?)"
).setConsistencyLevel(ConsistencyLevel.QUORUM);

// 读取：同样用 QUORUM，配合写入 QUORUM 可实现强一致读
// 公式: R + W > N 时为强一致，QUORUM + QUORUM 满足此条件
PreparedStatement readStmt = session.prepare(
    "SELECT * FROM user_activity WHERE user_id = ? AND event_time > ?"
).setConsistencyLevel(ConsistencyLevel.QUORUM);

// 如果用 ONE 读写，则只有最终一致保证
// 反熵修复机制: Read Repair（读时发现不一致自动修复）
//               Hinted Handoff（宕机期间写入暂存，恢复后回放）
//               Anti-Entropy Repair（nodetool repair 全量对比修复）
